export const DEFAULT_PREFIX = "m";
const sources = new Map();
const fallbackStyles = new WeakSet();
export const styleText = (name) => sources.get(name);
export const isFallbackStyle = (node) => fallbackStyles.has(node);
const sheets = new Map();
export const registerStyles = (css) => {
    for (const [name, text] of Object.entries(css)) {
        sources.set(name, text);
        sheets.delete(name);
    }
};
export const hasStyles = (name) => sources.has(name);
const canAdopt = () => typeof CSSStyleSheet === "function" &&
    "replaceSync" in CSSStyleSheet.prototype &&
    typeof ShadowRoot === "function" &&
    "adoptedStyleSheets" in ShadowRoot.prototype;
const sheetFor = (name, text) => {
    let sheet = sheets.get(name);
    if (!sheet) {
        sheet = new CSSStyleSheet();
        sheet.replaceSync(text);
        sheets.set(name, sheet);
    }
    return sheet;
};
const PREUPGRADE_LAYER = "mtrl.preupgrade";
export const RENDERED_HOST_ATTRIBUTE = "data-mtrl-ssr";
export const preupgradeRollback = () => {
    const selector = `[${RENDERED_HOST_ATTRIBUTE}]:not(:defined):not(#\\0)`;
    return `${selector},${selector}::before,${selector}::after,${selector} > :defined{all:revert-layer}`;
};
export const retagPreupgrade = (css, prefix) => prefix === DEFAULT_PREFIX ? css : css.replace(/(^|[\s,>+~({}])m-(?=[a-z])/g, `$1${prefix}-`);
export const preupgradeSheet = (css, prefixes = [DEFAULT_PREFIX]) => `@layer ${PREUPGRADE_LAYER}{${Array.from(prefixes, (prefix) => retagPreupgrade(css, prefix)).join("")}${preupgradeRollback()}}`;
export const applyStyles = (root, names) => {
    const known = names.filter((name) => sources.has(name));
    if (canAdopt()) {
        root.adoptedStyleSheets = known.map((name) => sheetFor(name, sources.get(name)));
        return;
    }
    for (const name of known) {
        const style = document.createElement("style");
        style.textContent = sources.get(name);
        fallbackStyles.add(style);
        root.append(style);
    }
};
